      "path": "truth-reader/engine.js",
      "purpose": "Workflow-only Node.js engine for parsing sources, interleaving seeds, and validating evidence.",
      "content": "const fs = require('fs');
const path = require('path');
const crypto = require('crypto');

const ROOT_DIR = path.resolve(__dirname, '..');
const CATALOG_PATH = path.join(__dirname, 'catalog.json');
const SELECTOR_PATH = path.join(__dirname, 'selector.json');
const EVIDENCE_PATH = path.join(__dirname, 'evidence.json');
const STATUS_PATH = path.join(__dirname, 'status.json');
const STATE_PATH = path.join(__dirname, 'state', 'expected_seeds.json');

function readJson(filePath) {
  return JSON.parse(fs.readFileSync(filePath, 'utf8'));
}

function writeJson(filePath, data) {
  fs.writeFileSync(filePath, JSON.stringify(data, null, 2) + '\n', 'utf8');
}

function generateSeed() {
  return crypto.randomBytes(16).toString('hex');
}

function parseMarkdown(content) {
  const elements = [];
  const lines = content.split(/\r?\n/);
  let currentTopic = null;
  let inCodeBlock = false;
  let paragraphBuffer = [];
  let elementIndex = 0;

  function flushParagraph() {
    if (paragraphBuffer.length > 0) {
      elements.push({
        type: 'content',
        element_type: 'paragraph',
        index: elementIndex++,
        topic: currentTopic,
        text: paragraphBuffer.join('\n')
      });
      paragraphBuffer = [];
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];

    if (line.trim().startsWith('```')) {
      flushParagraph();
      inCodeBlock = !inCodeBlock;
      elements.push({
        type: 'content',
        element_type: 'code_fence',
        index: elementIndex++,
        topic: currentTopic,
        text: line
      });
      continue;
    }

    if (inCodeBlock) {
      elements.push({
        type: 'content',
        element_type: 'code_line',
        index: elementIndex++,
        topic: currentTopic,
        text: line
      });
      continue;
    }

    const headingMatch = line.match(/^(#{1,6})\s+(.*)$/);
    if (headingMatch) {
      flushParagraph();
      currentTopic = headingMatch[2].trim();
      elements.push({
        type: 'content',
        element_type: 'heading',
        index: elementIndex++,
        topic: currentTopic,
        text: line
      });
      continue;
    }

    const isTableRow = line.trim().startsWith('|');
    const isListItem = /^\s*([*+-]|\d+\.)\s+/.test(line);

    if (isTableRow || isListItem) {
      flushParagraph();
      elements.push({
        type: 'content',
        element_type: isTableRow ? 'table_row' : 'list_item',
        index: elementIndex++,
        topic: currentTopic,
        text: line
      });
      continue;
    }

    if (line.trim() === '') {
      flushParagraph();
      elements.push({
        type: 'content',
        element_type: 'blank_line',
        index: elementIndex++,
        topic: currentTopic,
        text: ''
      });
      continue;
    }

    paragraphBuffer.push(line);
  }
  flushParagraph();
  return elements;
}

function flattenJson(value) {
  const elements = [];
  let elementIndex = 0;

  function traverse(node, currentPath) {
    if (node === null) {
      elements.push({
        type: 'content',
        element_type: 'json_leaf',
        index: elementIndex++,
        path: currentPath || '$',
        value_type: 'null',
        value: null
      });
      return;
    }

    if (Array.isArray(node)) {
      if (node.length === 0) {
        elements.push({
          type: 'content',
          element_type: 'json_empty_array',
          index: elementIndex++,
          path: currentPath || '$',
          value_type: 'array',
          value: []
        });
        return;
      }
      for (let i = 0; i < node.length; i++) {
        traverse(node[i], `${currentPath || '$'}[${i}]`);
      }
      return;
    }

    if (typeof node === 'object') {
      const keys = Object.keys(node);
      if (keys.length === 0) {
        elements.push({
          type: 'content',
          element_type: 'json_empty_object',
          index: elementIndex++,
          path: currentPath || '$',
          value_type: 'object',
          value: {}
        });
        return;
      }
      for (const k of keys) {
        traverse(node[k], currentPath ? `${currentPath}.${k}` : `$.${k}`);
      }
      return;
    }

    elements.push({
      type: 'content',
      element_type: 'json_leaf',
      index: elementIndex++,
      path: currentPath || '$',
      value_type: typeof node,
      value: node
    });
  }

  traverse(value, '');
  return elements;
}

function interleaveSeeds(contentElements, docId, seedCollector) {
  const projection = [];
  const count = contentElements.length;

  if (count === 0) {
    const seedVal = generateSeed();
    seedCollector.push(seedVal);
    projection.push({
      type: 'truth_seed',
      seed_id: `${docId}_seed_0`,
      doc_id: docId,
      seed_position: 'empty_document',
      value: seedVal
    });
    return projection;
  }

  const interval = Math.max(3, Math.floor(count / 4));
  const seedInsertAfterIndices = new Set();
  seedInsertAfterIndices.add(0);
  for (let idx = interval; idx < count - 1; idx += interval) {
    seedInsertAfterIndices.add(idx);
  }
  seedInsertAfterIndices.add(count - 1);

  let seedCounter = 0;
  for (let i = 0; i < count; i++) {
    projection.push(contentElements[i]);
    if (seedInsertAfterIndices.has(i)) {
      const seedVal = generateSeed();
      seedCollector.push(seedVal);
      projection.push({
        type: 'truth_seed',
        seed_id: `${docId}_seed_${seedCounter++}`,
        doc_id: docId,
        seed_position: i === 0 ? 'beginning' : (i === count - 1 ? 'end' : 'intermediate'),
        after_content_index: i,
        value: seedVal
      });
    }
  }

  return projection;
}

function runPrepare() {
  const catalogData = readJson(CATALOG_PATH).catalog;
  const selectorData = readJson(SELECTOR_PATH);

  if (!selectorData || typeof selectorData.selected !== 'object') {
    throw new Error('Invalid selector.json structure: missing selected map.');
  }

  for (const key of Object.keys(selectorData.selected)) {
    if (!catalogData[key]) {
      throw new Error(`Rejected unauthorized document key: ${key}`);
    }
    if (typeof selectorData.selected[key] !== 'boolean') {
      throw new Error(`Selector value for ${key} must be a boolean.`);
    }
  }

  const selectedDocIds = Object.keys(catalogData).filter(
    (docId) => selectorData.selected[docId] === true
  );

  if (selectedDocIds.length === 0) {
    console.log('No documents selected for projection generation.');
    return;
  }

  console.log(`Generating reading projections for: ${selectedDocIds.join(', ')}`);
  const orderedExpectedSeeds = [];

  for (const docId of selectedDocIds) {
    const entry = catalogData[docId];
    const fullSourcePath = path.join(ROOT_DIR, entry.source_path);
    const fullProjectionPath = path.join(ROOT_DIR, entry.projection_path);

    if (!fs.existsSync(fullSourcePath)) {
      throw new Error(`Authoritative source file not found: ${entry.source_path}`);
    }

    const rawContent = fs.readFileSync(fullSourcePath, 'utf8');
    let contentElements;

    if (entry.format === 'json') {
      const parsed = JSON.parse(rawContent);
      contentElements = flattenJson(parsed);
    } else {
      contentElements = parseMarkdown(rawContent);
    }

    const seededProjection = interleaveSeeds(contentElements, docId, orderedExpectedSeeds);
    writeJson(fullProjectionPath, seededProjection);
  }

  writeJson(STATE_PATH, {
    active: true,
    selected_docs: selectedDocIds,
    seeds: orderedExpectedSeeds
  });

  writeJson(STATUS_PATH, {
    last_status: 'PROJECTIONS_GENERATED',
    last_run_timestamp: new Date().toISOString(),
    selected_docs: selectedDocIds,
    seed_count: orderedExpectedSeeds.length,
    message: 'Projections generated and truth seeds distributed across content.'
  });

  console.log(`Successfully generated projections. Total distributed seeds: ${orderedExpectedSeeds.length}.`);
}

function runVerify() {
  const state = readJson(STATE_PATH);
  if (!state.active || !Array.isArray(state.seeds) || state.seeds.length === 0) {
    console.error('Verification failed: No active truth-reading challenge found.');
    process.exit(1);
  }

  const evidence = readJson(EVIDENCE_PATH);
  const expectedSeeds = state.seeds;
  const submittedSeeds = evidence.seeds;

  if (!Array.isArray(submittedSeeds)) {
    console.error('Verification failed: evidence.seeds must be an array.');
    process.exit(1);
  }

  if (submittedSeeds.length !== expectedSeeds.length) {
    console.error(`Verification failed: Expected ${expectedSeeds.length} seeds, received ${submittedSeeds.length}.`);
    process.exit(1);
  }

  for (let i = 0; i < expectedSeeds.length; i++) {
    const expected = expectedSeeds[i];
    const submitted = submittedSeeds[i];
    if (typeof submitted !== 'string' || submitted.length !== expected.length) {
      console.error(`Verification failed: Mismatch at seed index ${i}.`);
      process.exit(1);
    }
    const bufExpected = Buffer.from(expected, 'utf8');
    const bufSubmitted = Buffer.from(submitted, 'utf8');
    if (!crypto.timingSafeEqual(bufExpected, bufSubmitted)) {
      console.error(`Verification failed: Mismatch at seed index ${i}.`);
      process.exit(1);
    }
  }

  console.log(`Verification PASSED: Exactly matched all ${expectedSeeds.length} seeds in projection order.`);

  const catalogData = readJson(CATALOG_PATH).catalog;
  const resetSelected = {};
  for (const docId of Object.keys(catalogData)) {
    resetSelected[docId] = false;
  }
  writeJson(SELECTOR_PATH, { selected: resetSelected });
  writeJson(EVIDENCE_PATH, { seeds: [] });
  writeJson(STATE_PATH, { active: false, selected_docs: [], seeds: [] });

  for (const docId of Object.keys(catalogData)) {
    const fullProjPath = path.join(ROOT_DIR, catalogData[docId].projection_path);
    writeJson(fullProjPath, []);
  }

  writeJson(STATUS_PATH, {
    last_status: 'PASS',
    last_run_timestamp: new Date().toISOString(),
    last_passed_selection: state.selected_docs,
    seed_count_verified: expectedSeeds.length,
    message: 'All seeds verified in exact projection order. Atomic cleanup complete.'
  });

  console.log('Atomic cleanup commit prepared.');
}

function main() {
  const mode = process.argv[2] || 'auto';
  if (mode === 'prepare') {
    runPrepare();
  } else if (mode === 'verify') {
    runVerify();
  } else if (mode === 'auto') {
    const evidence = readJson(EVIDENCE_PATH);
    const state = readJson(STATE_PATH);
    if (evidence && Array.isArray(evidence.seeds) && evidence.seeds.length > 0 && state.active) {
      runVerify();
    } else {
      runPrepare();
    }
  } else {
    console.error(`Unknown execution mode: ${mode}`);
    process.exit(1);
  }
}

main();
