    {
      "path": ".github/workflows/truth-reader.yml",
      "purpose": "GitHub Actions workflow for truth-reader execution, ensuring seed privacy and recursion suppression.",
      "content": "name: Truth Reader Automation

on:
  push:
    paths:
      - 'truth-reader/selector.json'
      - 'truth-reader/evidence.json'
    branches:
      - main
      - master

permissions:
  contents: write

jobs:
  execute_cycle:
    if: "!contains(github.event.head_commit.message, '[skip ci]')"
    runs-on: ubuntu-latest
    steps:
      - name: Checkout repository
        uses: actions/checkout@v4
        with:
          token: ${{ secrets.GITHUB_TOKEN }}
          fetch-depth: 2

      - name: Setup Node.js runtime
        uses: actions/setup-node@v4
        with:
          node-version: '20'

      - name: Detect trigger file
        id: detect_trigger
        run: |
          MODIFIED=$(git diff --name-only HEAD~1 HEAD || true)
          echo "Modified files in commit:"
          echo "$MODIFIED"
          if echo "$MODIFIED" | grep -q "truth-reader/evidence.json"; then
            echo "mode=verify" >> $GITHUB_OUTPUT
          elif echo "$MODIFIED" | grep -q "truth-reader/selector.json"; then
            echo "mode=prepare" >> $GITHUB_OUTPUT
          else
            echo "mode=auto" >> $GITHUB_OUTPUT
          fi

      - name: Run Truth Reader Authority Engine
        run: |
          node truth-reader/engine.js ${{ steps.detect_trigger.outputs.mode }}

      - name: Commit and push changes on PASS or projection generation
        run: |
          git config user.name "github-actions[bot]"
          git config user.email "github-actions[bot]@users.noreply.github.com"
          if [ -n "$(git status --porcelain truth-reader/)" ]; then
            git add truth-reader/
            git commit -m "[skip ci] truth-reader: automated atomic state transition"
            git push
          else
            echo "No repository mutations required."
          fi
"
    }
  ],
  "design_checks": {
    "authoritative_docs_immutable": true,
    "enumerated_doc_selector": true,
    "projection_from_current_source": true,
    "all_projections_are_json": true,
    "non_json_full_content_preserved": true,
    "distributed_seed_coverage": true,
    "workflow_only_seed_authority": true,
    "exact_complete_seed_match": true,
    "fail_is_noop": true,
    "pass_atomic_cleanup": true,
    "recursive_workflow_loop_prevented": true
  },
  "unresolved_requirements": []
}
